import { storage } from "./storage.js";

// ————— Study signal —————
// HAND-MAINTAINED. Not generated by build-vite-app.py.
//
// A one-line publish/subscribe bus carrying a single fact: "the learner just
// did real work in module X." App.jsx publishes it; the engagement panel
// subscribes.
//
// ⚠️ WHAT COUNTS AS "REAL WORK", AND WHY IT IS NOT NAVIGATION. The engagement
// module's §5 is emphatic that opening the app must not mark a day active — a
// draft that did so was thrown out, because it would show a full week to
// someone who launched the app seven times and studied nothing. So this is
// never published on navigation. App.jsx publishes it from commitIfWorked(),
// which snapshots the module's own progress store on the way in and compares on
// the way out: the store changing IS the evidence, and the module already
// writes it without being asked.
//
// WHAT IS NOT COVERED, so nobody reads a quiet quest chain as a bug:
//   · the Checker writes no progress key, so "write and check one sentence"
//     cannot be credited this way and stays dark
//   · a key change cannot tell a finished SET from a cleared REVIEW, so
//     reportActivity is called without a `kind` — the module credits the first
//     unfinished task for that module, which is right for chains built from one
//     task per module and approximate for chains that are not
// Closing both needs the seven call sites listed in §5 of engagement-module.jsx,
// inside the modules themselves. That is a bigger, riskier change than this one
// and is deliberately not bundled with it.

// ⚠️ WHY THIS IS A QUEUE AND NOT A PLAIN EVENT. The panel lives on Home, so it
// is UNMOUNTED for the entire time the learner is inside a module — which is
// exactly when the studying happens. App.jsx publishes from commitIfWorked(),
// which runs during go("home"): the old Home is gone and the new one has not
// rendered yet, so a fire-and-forget event reaches nobody. Worse, it fails
// silently and looks like "the rhythm target is broken".
//
// Caught Sep 6 2026 by driving it in a browser rather than reasoning about it:
// entering hiragana, changing the module's own progress store, and coming back
// left activeDays empty. Both halves of the check mattered — navigating in and
// out WITHOUT working also left it empty, which is the property that must not
// regress.
//
// So a report is held until something is listening, and held THROUGH A RELOAD,
// because the other way to leave a module is to close the tab. Held in the same
// storage adapter every module uses, so a private window degrades the same way
// everything else does rather than differently.
const PENDING_KEY = "naoshi-pending-study";

const subs = new Set();

async function readPending() {
  try {
    const r = await storage.get(PENDING_KEY);
    const v = r ? JSON.parse(r.value) : [];
    return Array.isArray(v) ? v : [];
  } catch { return []; }
}

async function writePending(list) {
  try { await storage.set(PENDING_KEY, JSON.stringify(list.slice(-40))); }
  catch (e) { console.error("pending study write failed", e); }
}

// App.jsx's module ids are the app's; the engagement module has its own names
// for the same things. One map, in one direction, in one place.
const TO_ENGAGEMENT = {
  hiragana: "hiragana",
  katakana: "katakana",
  kanji: "kanji",
  vocabulary: "vocab",
  grammar: "grammar",
  checker: "checker",
};

export function reportStudy(appModuleId) {
  const id = TO_ENGAGEMENT[appModuleId];
  if (!id) return;
  if (subs.size) {
    deliver(id);
    return;
  }
  // Nobody listening: hold it. Read-then-write rather than append-in-place, so
  // two reports in one session cannot clobber each other.
  readPending().then((list) => writePending([...list, id]));
}

function deliver(id) {
  for (const fn of subs) {
    try { fn(id); } catch (e) { console.error("study subscriber failed", e); }
  }
}

export function onStudy(fn) {
  subs.add(fn);
  // Drain whatever accumulated while nothing was mounted. CLEARED BEFORE
  // DELIVERY, not after: reportActivity advances a quest task, so replaying a
  // report because the clear failed would over-credit it. Losing one is the
  // cheaper mistake of the two.
  (async () => {
    const list = await readPending();
    if (!list.length) return;
    await writePending([]);
    for (const id of list) deliver(id);
  })();
  return () => subs.delete(fn);
}
